import heapq


def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)
    adj = [[] for _ in range(n)]
    for u, v, minutes, energy in roads:
        adj[u].append((v, minutes, energy))
    is_station = [False] * n
    for x in stations:
        is_station[x] = True
    C, K = capacity, max_swaps
    INF = float("inf")
    W = C + 1
    dist = [INF] * (n * W * (K + 1))

    def idx(v, c, k):
        return (v * W + c) * (K + 1) + k

    dist[idx(s, C, 0)] = 0
    pq = [(0, s, C, 0)]
    while pq:
        d, v, c, k = heapq.heappop(pq)
        if d > dist[idx(v, c, k)]:
            continue
        if is_station[v] and k < K:
            nd = d + swap_time
            j = idx(v, C, k + 1)
            if nd < dist[j]:
                dist[j] = nd
                heapq.heappush(pq, (nd, v, C, k + 1))
        for w, minutes, energy in adj[v]:
            if c < energy:
                continue
            nc = c - energy
            if nc > C:
                nc = C
            nd = d + minutes
            j = idx(w, nc, k)
            if nd < dist[j]:
                dist[j] = nd
                heapq.heappush(pq, (nd, w, nc, k))
    best = None
    for c in range(W):
        for k in range(K + 1):
            d = dist[idx(t, c, k)]
            if d < INF and (best is None or (d, k) < best):
                best = (d, k)
    return best

def earliest_arrival(connections, transfer, source, target, start_time, max_boardings):
    if source == target:
        return start_time
    by_trip = {}
    for c in connections:
        by_trip.setdefault(c[0], []).append(c)
    trips = [sorted(v, key=lambda c: c[3]) for v in by_trip.values()]
    station_trips = {}
    for ti, trip in enumerate(trips):
        for c in trip:
            station_trips.setdefault(c[1], set()).add(ti)
    INF = float("inf")
    ready = {source: start_time}  # earliest time one can board at a station (fewer boardings than this round)
    best = INF
    marked = {source}
    rounds = 0
    while marked and rounds < max_boardings:
        rounds += 1
        to_scan = set()
        for x in marked:
            to_scan |= station_trips.get(x, set())
        arrivals = {}
        for ti in to_scan:
            on = False
            for _, frm, to, dep, arr in trips[ti]:
                if not on:
                    r = ready.get(frm)
                    if r is not None and r <= dep:
                        on = True
                if on and arr < arrivals.get(to, INF):
                    arrivals[to] = arr
        marked = set()
        for x, a in arrivals.items():
            if x == target and a < best:
                best = a
            rr = a + transfer[x]
            if rr < ready.get(x, INF):
                ready[x] = rr
                marked.add(x)
    return None if best == INF else best

from collections import deque


def run_kiosk(levels, threshold, patience, arrivals):
    for a, b in zip(arrivals, arrivals[1:]):
        if b[0] < a[0]:
            raise ValueError("arrivals out of order")
    slots = [[c, 0] for c in levels]  # [charge when placed, time placed]
    out = []
    queue = deque()  # (drone, arrival time)
    n = len(arrivals)
    i = 0

    def best(t):
        bk, bc = -1, -1
        for k, (c0, t0) in enumerate(slots):
            c = c0 + t - t0
            if c > 100:
                c = 100
            if c >= threshold and c > bc:
                bk, bc = k, c
        return bk

    def swap(drone, charge, t, k):
        slots[k] = [charge, t]
        out.append((drone, "SWAP", t, k))

    charge_of = {}
    while i < n or queue:
        cands = []
        if i < n:
            cands.append(arrivals[i][0])
        if queue:
            cands.append(queue[0][1] + patience)
            cands.append(min(t0 + max(0, threshold - c0) for c0, t0 in slots))
        t = min(cands)
        while queue:
            k = best(t)
            if k < 0:
                break
            d, _ = queue.popleft()
            swap(d, charge_of.pop(d), t, k)
        while i < n and arrivals[i][0] == t:
            _, d, c = arrivals[i]
            i += 1
            k = best(t) if not queue else -1
            if k >= 0:
                swap(d, c, t, k)
            else:
                charge_of[d] = c
                queue.append((d, t))
        while queue and queue[0][1] + patience <= t:
            d, _ = queue.popleft()
            charge_of.pop(d)
            out.append((d, "LEFT", t))
    return out

def run_lock_manager(ops):
    holders = {}   # res -> {tx: mode}
    queues = {}    # res -> list of [tx, mode, is_upgrade]
    held = {}      # tx -> set of res
    waiting = {}   # tx -> res it is queued on
    finished = set()
    log = []

    def compatible(mode, res, me):
        for h, m in holders.get(res, {}).items():
            if h != me and (mode == "X" or m == "X"):
                return False
        return True

    def process_queue(i, res):
        q = queues.get(res)
        while q:
            tx, mode, _ = q[0]
            if not compatible(mode, res, tx):
                break
            q.pop(0)
            holders.setdefault(res, {})[tx] = mode
            held.setdefault(tx, set()).add(res)
            del waiting[tx]
            log.append(("GRANT", i, tx, res, mode))

    def release(i, tx):
        affected = set()
        r = waiting.pop(tx, None)
        if r is not None:
            queues[r] = [e for e in queues[r] if e[0] != tx]
            affected.add(r)
        for r2 in held.pop(tx, ()):
            del holders[r2][tx]
            affected.add(r2)
        finished.add(tx)
        for r2 in sorted(affected):
            process_queue(i, r2)

    def out_edges(w, posc):
        # Reachability-equivalent edge set: a queued request points at its predecessor in the
        # queue; the front request points at the incompatible holders.
        res = waiting[w]
        q = queues[res]
        if res not in posc:
            posc[res] = {e[0]: k for k, e in enumerate(q)}
        pos = posc[res][w]
        if pos > 0:
            return [q[pos - 1][0]]
        mode = q[0][1]
        return [h for h, m in holders.get(res, {}).items() if h != w and (mode == "X" or m == "X")]

    def cycle_members(start):
        # nodes on a cycle through `start` (every cycle created by a new wait passes through it)
        if start not in waiting:
            return []
        posc = {}
        fwd = {start: out_edges(start, posc)}
        stack = [start]
        while stack:
            u = stack.pop()
            for v in fwd[u]:
                if v not in fwd:
                    fwd[v] = out_edges(v, posc) if v in waiting else []
                    stack.append(v)
        rev = {}
        for u, vs in fwd.items():
            for v in vs:
                rev.setdefault(v, []).append(u)
        if start not in rev:
            return []
        back = {start}
        stack = [start]
        while stack:
            u = stack.pop()
            for v in rev.get(u, ()):
                if v not in back:
                    back.add(v)
                    stack.append(v)
        return list(back)

    for i, op in enumerate(ops):
        tx = op[1]
        if tx in waiting or tx in finished:
            log.append(("IGNORED", i, tx))
            continue
        if op[0] == "COMMIT":
            log.append(("COMMIT", i, tx))
            release(i, tx)
            continue
        mode, res = op[0], op[2]
        mine = holders.get(res, {}).get(tx)
        if mine == "X" or (mine == "S" and mode == "S"):
            log.append(("HELD", i, tx, res))
            continue
        if mine == "S":
            if len(holders[res]) == 1:
                holders[res][tx] = "X"
                log.append(("GRANT", i, tx, res, "X"))
                continue
            q = queues.setdefault(res, [])
            k = 0
            while k < len(q) and q[k][2]:
                k += 1
            q.insert(k, [tx, "X", True])
        else:
            q = queues.setdefault(res, [])
            if not q and compatible(mode, res, tx):
                holders.setdefault(res, {})[tx] = mode
                held.setdefault(tx, set()).add(res)
                log.append(("GRANT", i, tx, res, mode))
                continue
            q.append([tx, mode, False])
        waiting[tx] = res
        log.append(("WAIT", i, tx, res, "X" if mine == "S" else mode))
        while True:
            members = cycle_members(tx)
            if not members:
                break
            victim = max(members)
            log.append(("ABORT", i, victim))
            release(i, victim)
    return log

DENOMS = (100, 25, 10, 5)


def simulate_vending(prices, stock, bank, events, timeout):
    prev = None
    for ev in events:
        if prev is not None and ev[0] < prev:
            raise ValueError("events out of order")
        prev = ev[0]
    stock = dict(stock)
    bk = {d: bank.get(d, 0) for d in DENOMS}
    escrow = []
    log = []
    last = None

    def flush_if_due(t):
        if escrow and (t is None or t >= last + timeout):
            log.append(("TIMEOUT", last + timeout, tuple(sorted(escrow, reverse=True))))
            escrow.clear()

    for t, kind, arg in events:
        flush_if_due(t)
        if kind == "coin":
            if arg not in DENOMS or len(escrow) >= 10:
                log.append(("REJECT", t, arg))
                continue
            escrow.append(arg)
            last = t
        elif kind == "select":
            last = t
            if arg not in prices:
                log.append(("UNKNOWN", t, arg))
                continue
            if stock[arg] == 0:
                log.append(("SOLD_OUT", t, arg))
                continue
            total = sum(escrow)
            price = prices[arg]
            if total < price:
                log.append(("NEED", t, price - total))
                continue
            trial = dict(bk)
            for c in escrow:
                trial[c] += 1
            rem = total - price
            change = []
            for d in DENOMS:
                k = min(trial[d], rem // d)
                if k:
                    trial[d] -= k
                    rem -= k * d
                    change.extend([d] * k)
            if rem:
                log.append(("EXACT_ONLY", t, arg))
                continue
            bk = trial
            stock[arg] -= 1
            escrow.clear()
            log.append(("VEND", t, arg, tuple(change)))
        elif kind == "cancel":
            last = t
            if escrow:
                log.append(("RETURN", t, tuple(sorted(escrow, reverse=True))))
                escrow.clear()
    flush_if_due(None)
    return log, (bk[5], bk[10], bk[25], bk[100])

NAME_CHARS = set("abcdefghijklmnopqrstuvwxyz0123456789_")
SEG_CHARS = NAME_CHARS | set(".-")
ACTION_CHARS = set("abcdefghijklmnopqrstuvwxyz")


def _name_ok(s):
    return isinstance(s, str) and s != "" and all(c in NAME_CHARS for c in s)


def _segments(path, allow_wild):
    if not isinstance(path, str) or not path.startswith("/"):
        return None
    if path == "/":
        return []
    segs = path[1:].split("/")
    for s in segs:
        if allow_wild and s in ("*", "**"):
            continue
        if not s or any(c not in SEG_CHARS for c in s):
            return None
    return segs


def _parse_rule(i, rule):
    if not isinstance(rule, str):
        raise TypeError("rule %d: not a str" % i)
    f = rule.split()
    if len(f) != 4:
        raise ValueError("rule %d: expected 4 fields, got %d" % (i, len(f)))
    effect, principal, action, resource = f
    if effect not in ("ALLOW", "DENY"):
        raise ValueError("rule %d: bad effect %r" % (i, effect))
    if principal == "*":
        pk = ("any", None)
    elif principal.startswith("user:") and _name_ok(principal[5:]):
        pk = ("user", principal[5:])
    elif principal.startswith("group:") and _name_ok(principal[6:]):
        pk = ("group", principal[6:])
    else:
        raise ValueError("rule %d: bad principal %r" % (i, principal))
    if action == "*":
        acts = None
    else:
        acts = action.split(",")
        if any(not a or any(c not in ACTION_CHARS for c in a) for a in acts):
            raise ValueError("rule %d: bad action %r" % (i, action))
        acts = set(acts)
    segs = _segments(resource, True)
    if segs is None:
        raise ValueError("rule %d: bad resource %r" % (i, resource))
    literal = sum(1 for s in segs if s not in ("*", "**"))
    spec = (literal, {"user": 2, "group": 1, "any": 0}[pk[0]], 0 if acts is None else 1)
    return {"deny": effect == "DENY", "pk": pk, "acts": acts, "segs": segs, "spec": spec, "idx": i}


def _match(pat, path):
    # DP over (pattern position, path position); "**" consumes zero or more segments
    n, m = len(pat), len(path)
    reach = [False] * (m + 1)
    reach[0] = True
    for p in pat:
        nxt = [False] * (m + 1)
        if p == "**":
            run = False
            for j in range(m + 1):
                run = run or reach[j]
                nxt[j] = run
        else:
            for j in range(m):
                if reach[j] and (p == "*" or p == path[j]):
                    nxt[j + 1] = True
        reach = nxt
        if not any(reach):
            return False
    return reach[m]


def evaluate_access(rules, requests):
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")
    parsed = [_parse_rule(i, r) for i, r in enumerate(rules)]
    reqs = []
    for j, rq in enumerate(requests):
        if not isinstance(rq, tuple) or len(rq) != 4:
            raise TypeError("request %d: expected 4-tuple" % j)
        user, groups, action, path = rq
        if not _name_ok(user):
            raise ValueError("request %d: bad user %r" % (j, user))
        if not isinstance(groups, list) or not all(_name_ok(g) for g in groups):
            raise ValueError("request %d: bad groups" % j)
        if not isinstance(action, str) or not action or any(c not in ACTION_CHARS for c in action):
            raise ValueError("request %d: bad action %r" % (j, action))
        segs = _segments(path, False)
        if segs is None:
            raise ValueError("request %d: bad path %r" % (j, path))
        reqs.append((user, set(groups), action, segs))
    # most specific first; within equal specificity DENY first, then lowest index
    ordered = sorted(parsed, key=lambda r: (-r["spec"][0], -r["spec"][1], -r["spec"][2], not r["deny"], r["idx"]))
    out = []
    for user, groups, action, segs in reqs:
        verdict = "DENY by default"
        for r in ordered:
            kind, name = r["pk"]
            if kind == "user" and name != user:
                continue
            if kind == "group" and name not in groups:
                continue
            if r["acts"] is not None and action not in r["acts"]:
                continue
            if not _match(r["segs"], segs):
                continue
            verdict = "%s by rule %d" % ("DENY" if r["deny"] else "ALLOW", r["idx"])
            break
        out.append(verdict)
    return out

import copy
import json
import re

_IDENT = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _child(path, name):
    if _IDENT.fullmatch(name):
        return path + "." + name
    return path + "[" + json.dumps(name, ensure_ascii=False) + "]"


def _cat(v):
    if isinstance(v, bool):
        return "bool"
    if v is None:
        return "null"
    for t, n in ((dict, "dict"), (list, "list"), (str, "str"), (int, "int"), (float, "float")):
        if isinstance(v, t):
            return n
    return type(v).__name__


def _merge_into(target, overlay, path, layer, warnings):
    for key, val in overlay.items():
        if not isinstance(key, str):
            raise TypeError("layer %d: non-string key at %s" % (layer, path))
        if key.startswith("-"):
            name = key[1:]
            if not name:
                raise ValueError("layer %d: empty key name at %s" % (layer, path))
            p = _child(path, name)
            if val is not None:
                raise ValueError("layer %d: delete directive needs null at %s" % (layer, p))
            if name in target:
                del target[name]
            else:
                warnings.append("layer %d: delete of missing key at %s" % (layer, p))
        elif key.endswith("+"):
            name = key[:-1]
            if not name:
                raise ValueError("layer %d: empty key name at %s" % (layer, path))
            p = _child(path, name)
            if not isinstance(val, list):
                raise ValueError("layer %d: append directive needs a list at %s" % (layer, p))
            if name not in target:
                target[name] = copy.deepcopy(val)
            elif isinstance(target[name], list):
                target[name].extend(copy.deepcopy(val))
            else:
                raise ValueError("layer %d: cannot append to %s at %s" % (layer, _cat(target[name]), p))
        else:
            if not key:
                raise ValueError("layer %d: empty key name at %s" % (layer, path))
            p = _child(path, key)
            if key in target and _cat(target[key]) != _cat(val):
                warnings.append("layer %d: type change at %s: %s -> %s" % (layer, p, _cat(target[key]), _cat(val)))
            if isinstance(val, dict):
                if not (key in target and isinstance(target[key], dict)):
                    target[key] = {}
                _merge_into(target[key], val, p, layer, warnings)
            else:
                target[key] = copy.deepcopy(val)


def merge_layers(layers):
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")
    result, warnings = {}, []
    for i, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError("layer %d is not a dict" % i)
        _merge_into(result, layer, "$", i, warnings)
    return result, warnings

DIGITS = "0123456789"


def _days_in_month(y, m):
    if m == 2:
        return 29 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 28
    return 30 if m in (4, 6, 9, 11) else 31


def _valid_date(s):
    if not isinstance(s, str) or len(s) != 10 or s[4] != "-" or s[7] != "-":
        return False
    parts = (s[0:4], s[5:7], s[8:10])
    if not all(ch in DIGITS for p in parts for ch in p):
        return False
    y, m, d = (int(p) for p in parts)
    return 1900 <= y <= 2999 and 1 <= m <= 12 and 1 <= d <= _days_in_month(y, m)


def _int_part_ok(s, max_len):
    if not s or len(s) > max_len or any(ch not in DIGITS for ch in s):
        return False
    return not (len(s) > 1 and s[0] == "0")


def _parse_amount(s):
    """Entry amount -> positive cents, or None."""
    if not isinstance(s, str):
        return None
    if "." in s:
        ip, fp = s.split(".", 1)
        if not (1 <= len(fp) <= 2) or any(ch not in DIGITS for ch in fp):
            return None
    else:
        ip, fp = s, ""
    if not _int_part_ok(ip, 9):
        return None
    cents = int(ip) * 100 + int((fp + "00")[:2])
    return cents if cents > 0 else None


def _parse_opening(s):
    if not isinstance(s, str):
        return None
    neg = s.startswith("-")
    body = s[1:] if neg else s
    if body.count(".") != 1:
        return None
    ip, fp = body.split(".")
    if len(fp) != 2 or any(ch not in DIGITS for ch in fp) or not _int_part_ok(ip, 9):
        return None
    v = int(ip) * 100 + int(fp)
    return -v if neg else v


def _money(c):
    sign = "-" if c < 0 else ""
    c = abs(c)
    whole = str(c // 100)
    groups = []
    while len(whole) > 3:
        groups.insert(0, whole[-3:])
        whole = whole[:-3]
    groups.insert(0, whole)
    return sign + ",".join(groups) + "." + str(c % 100).rjust(2, "0")


def _memo_ok(m):
    if not isinstance(m, str) or not m.split():
        return False
    return not any(ord(ch) < 32 or ord(ch) == 127 for ch in m)


def _memo_col(m):
    m = " ".join(m.split())
    if len(m) > 20:
        m = m[:19] + "~"
    return m.ljust(20)


def render_statement(opening, entries):
    if not isinstance(opening, str):
        raise TypeError("opening must be a str")
    bal = _parse_opening(opening)
    if bal is None:
        raise ValueError("opening: bad amount %r" % (opening,))
    if not isinstance(entries, list):
        raise TypeError("entries must be a list")
    parsed = []
    prev = None
    for i, e in enumerate(entries):
        if not isinstance(e, tuple) or len(e) != 4:
            raise TypeError("entry %d: expected 4-tuple" % i)
        date, kind, amount, memo = e
        if not _valid_date(date):
            raise ValueError("entry %d: bad date %r" % (i, date))
        if prev is not None and date < prev:
            raise ValueError("entry %d: date out of order" % i)
        prev = date
        if kind not in ("credit", "debit", "fee") or not isinstance(kind, str):
            raise ValueError("entry %d: bad kind %r" % (i, kind))
        cents = _parse_amount(amount)
        if cents is None:
            raise ValueError("entry %d: bad amount %r" % (i, amount))
        if not _memo_ok(memo):
            raise ValueError("entry %d: bad memo" % i)
        parsed.append((date, kind, cents, memo))

    lines = ["Opening balance: " + _money(bal)]
    counts = {"credit": 0, "debit": 0, "fee": 0}
    od_dates = set()

    def emit(date, kind, cents, memo):
        nonlocal bal
        bal += cents if kind == "credit" else -cents
        counts[kind] += 1
        amt = ("+" if kind == "credit" else "-") + _money(cents)
        lines.append("%s  %s  %s  %s%s" % (date, _memo_col(memo), amt.rjust(14), _money(bal).rjust(15),
                                           " OD" if bal < 0 else ""))

    for date, kind, cents, memo in parsed:
        emit(date, kind, cents, memo)
        if kind == "debit" and bal < 0 and date not in od_dates:
            od_dates.add(date)
            emit(date, "fee", 2500, "OVERDRAFT FEE")
    lines.append("Closing balance: " + _money(bal))
    lines.append("Credits: %d  Debits: %d  Fees: %d" % (counts["credit"], counts["debit"], counts["fee"]))
    return lines

DIG = "0123456789"


def _num(s):
    if not s or any(c not in DIG for c in s) or (len(s) > 1 and s[0] == "0"):
        return None
    return int(s)


def _version(s):
    """'X.Y.Z' or 'X.Y.Z~rcN' -> sortable key (X, Y, Z, released, N) or None."""
    if not isinstance(s, str):
        return None
    rc = None
    if "~" in s:
        s, tail = s.split("~", 1)
        if not tail.startswith("rc"):
            return None
        rc = _num(tail[2:])
        if rc is None or rc < 1:
            return None
    parts = s.split(".")
    if len(parts) != 3:
        return None
    nums = [_num(p) for p in parts]
    if None in nums:
        return None
    return (nums[0], nums[1], nums[2], 0 if rc is not None else 1, rc or 0)


def _clause(text):
    """Return a predicate over version keys, or None if the clause is invalid."""
    if text == "*":
        return lambda k: True
    if text.startswith("@"):
        parts = text[1:].split(".")
        if len(parts) != 2:
            return None
        x, y = _num(parts[0]), _num(parts[1])
        if x is None or y is None:
            return None
        return lambda k: k[0] == x and k[1] >= y
    if text.endswith(".*"):
        parts = text[:-2].split(".")
        if not 1 <= len(parts) <= 2:
            return None
        nums = [_num(p) for p in parts]
        if None in nums:
            return None
        return lambda k: list(k[:len(nums)]) == nums
    for op in (">=", "<=", "!=", ">", "<", "="):
        if text.startswith(op):
            v = _version(text[len(op):])
            if v is None:
                return None
            return {">=": lambda k: k >= v, "<=": lambda k: k <= v, "!=": lambda k: k != v,
                    ">": lambda k: k > v, "<": lambda k: k < v, "=": lambda k: k == v}[op]
    v = _version(text)
    if v is None:
        return None
    return lambda k: k == v


def pick_version(available, constraint):
    if not isinstance(available, list):
        raise TypeError("available must be a list")
    keys = []
    for i, s in enumerate(available):
        k = _version(s)
        if k is None:
            raise ValueError("invalid version at index %d: %r" % (i, s))
        keys.append(k)
    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")
    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")
    alternatives = []
    for a, alt in enumerate(constraint.split("|"), 1):
        alt = alt.strip(" ")
        rc_ok = alt.startswith("?")
        if rc_ok:
            alt = alt[1:].strip(" ")
        if not alt:
            raise ValueError("alternative %d is empty" % a)
        preds = []
        for c, clause in enumerate(alt.split(","), 1):
            clause = clause.strip(" ")
            p = _clause(clause)
            if p is None:
                raise ValueError("alternative %d, clause %d: invalid clause %r" % (a, c, clause))
            preds.append(p)
        alternatives.append((rc_ok, preds))
    best = None
    for s, k in zip(available, keys):
        if best is not None and k <= best[0]:
            continue
        for rc_ok, preds in alternatives:
            if (k[3] == 1 or rc_ok) and all(p(k) for p in preds):
                best = (k, s)
                break
    return best[1] if best else None

_KEY_START = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_")
_KEY_REST = _KEY_START | set("0123456789-")
_ESC = {"\\": "\\", '"': '"', "n": "\n", "t": "\t"}


class _Err(Exception):
    pass


def _scalar(v):
    if v[0] == '"':
        out, i = [], 1
        while i < len(v):
            ch = v[i]
            if ch == "\\":
                if i + 1 >= len(v) or v[i + 1] not in _ESC:
                    raise _Err("bad escape")
                out.append(_ESC[v[i + 1]])
                i += 2
            elif ch == '"':
                if i != len(v) - 1:
                    raise _Err("bad string")
                return "".join(out)
            else:
                out.append(ch)
                i += 1
        raise _Err("bad string")
    if v == "true":
        return True
    if v == "false":
        return False
    if v == "null":
        return None
    d = v[1:] if v[0] == "-" else v
    if d and d.isascii() and d.isdigit() and (d == "0" or d[0] != "0"):
        return int(v)
    return v


def _classify(rest):
    """-> (kind, key, is_opener, value)"""
    if rest == "-" or rest.startswith("- "):
        text = rest[2:].strip(" ")
        if not text:
            return ("item", None, True, None)
        return ("item", None, False, _scalar(text))
    idx = rest.find(":")
    if idx <= 0:
        raise _Err("invalid entry")
    key = rest[:idx]
    if key[0] not in _KEY_START or any(ch not in _KEY_REST for ch in key):
        raise _Err("invalid entry")
    after = rest[idx + 1:]
    if after.strip(" ") == "":
        return ("key", key, True, None)
    if after[0] != " ":
        raise _Err("invalid entry")
    return ("key", key, False, _scalar(after.strip(" ")))


def parse_outline(text):
    root = None
    stack = []          # frames: [indent, container, kind]
    pending = None      # (opener indent, container, slot)
    for lineno, line in enumerate(text.split("\n"), 1):
        j = 0
        while j < len(line) and line[j] in " \t":
            j += 1
        rest = line[j:]
        if rest == "" or rest[0] == "#":
            continue
        lead = line[:j]
        try:
            if "\t" in lead:
                raise _Err("tab in indentation")
            indent = j
            kind, key, opener, value = _classify(rest)
            if root is None:
                if indent != 0:
                    raise _Err("unexpected indent")
                root = {} if kind == "key" else []
                stack.append([0, root, kind])
                frame = stack[-1]
            elif pending is not None and indent > pending[0]:
                child = {} if kind == "key" else []
                pending[1][pending[2]] = child
                stack.append([indent, child, kind])
                frame = stack[-1]
            else:
                if indent > stack[-1][0]:
                    raise _Err("unexpected indent")
                while stack[-1][0] > indent:
                    stack.pop()
                if stack[-1][0] != indent:
                    raise _Err("inconsistent dedent")
                frame = stack[-1]
                if frame[2] != kind:
                    raise _Err("mixed block")
                if kind == "key" and key in frame[1]:
                    raise _Err("duplicate key '%s'" % key)
            pending = None
            cont = frame[1]
            if kind == "key":
                cont[key] = value
                slot = key
            else:
                cont.append(value)
                slot = len(cont) - 1
            if opener:
                pending = (indent, cont, slot)
        except _Err as e:
            return ("error", lineno, e.args[0])
    return ("ok", root)

import sys

_BUILTINS = {"dup", "drop", "swap", "over", "rot", "+", "-", "*", "/", "%", "<", "=",
             "if", "times", "while", "call", "dip"}
_ARITY = {"dup": 1, "drop": 1, "swap": 2, "over": 2, "rot": 3, "+": 2, "-": 2, "*": 2, "/": 2, "%": 2,
          "<": 2, "=": 2, "if": 3, "times": 2, "while": 2, "call": 1, "dip": 2}


class _Err(Exception):
    def __init__(self, idx, msg):
        self.idx, self.msg = idx, msg


class _Quote:
    __slots__ = ("start", "end")

    def __init__(self, start, end):
        self.start, self.end = start, end  # token range of the body (exclusive of brackets)


def _tokenize(src):
    toks, cur = [], []
    for ch in src:
        if ch in " \t\n\r":
            if cur:
                toks.append("".join(cur))
                cur = []
        elif ch in "[]":
            if cur:
                toks.append("".join(cur))
                cur = []
            toks.append(ch)
        else:
            cur.append(ch)
    if cur:
        toks.append("".join(cur))
    return toks


def _is_int(t):
    d = t[1:] if t.startswith("-") else t
    return d != "" and d.isascii() and d.isdigit()


def _structure(toks):
    match = {}
    stack = []
    i, n = 0, len(toks)
    while i < n:
        t = toks[i]
        if t == "[":
            stack.append(i)
        elif t == "]":
            if not stack or toks[stack[-1]] != "[":
                raise _Err(i, "unmatched ]")
            match[stack.pop()] = i
        elif t == ":":
            if stack:
                raise _Err(i, "misplaced :")
            if i + 1 >= n:
                raise _Err(i, "unclosed :")
            name = toks[i + 1]
            if name in ("[", "]", ":", ";") or _is_int(name) or name in _BUILTINS:
                raise _Err(i + 1, "bad name")
            stack.append(i)
            i += 1
        elif t == ";":
            if not stack or toks[stack[-1]] != ":":
                raise _Err(i, "unmatched ;")
            match[stack.pop()] = i
        i += 1
    if stack:
        raise _Err(stack[0], "unclosed " + toks[stack[0]])
    return match


def _render(v, toks, match):
    if isinstance(v, int):
        return v
    out, i = [], v.start
    while i < v.end:
        if toks[i] == "[":
            out.append(_render(_Quote(i + 1, match[i]), toks, match))
            i = match[i] + 1
        else:
            out.append(toks[i])
            i += 1
    return out


def run_pile(src, max_steps):
    toks = _tokenize(src)
    try:
        match = _structure(toks)
    except _Err as e:
        return ("error", e.idx, e.msg)
    words = {}
    stack = []
    steps = 0
    # frames: ["seq", pos, end] | ["times", quote, remaining] | ["while", cquote, bquote, idx] | ["push", value]
    frames = [["seq", 0, len(toks)]]
    try:
        while frames:
            fr = frames[-1]
            kind = fr[0]
            if kind == "seq":
                pos = fr[1]
                if pos >= fr[2]:
                    frames.pop()
                    continue
                t = toks[pos]
                steps += 1
                if steps > max_steps:
                    raise _Err(pos, "step limit exceeded")
                if t == "[":
                    fr[1] = match[pos] + 1
                    stack.append(_Quote(pos + 1, match[pos]))
                    continue
                if t == ":":
                    fr[1] = match[pos] + 1
                    words[toks[pos + 1]] = (pos + 2, match[pos])
                    continue
                fr[1] = pos + 1
                if _is_int(t):
                    stack.append(int(t))
                    continue
                if t in _BUILTINS:
                    if len(stack) < _ARITY[t]:
                        raise _Err(pos, "stack underflow")
                    if t == "dup":
                        stack.append(stack[-1])
                    elif t == "drop":
                        stack.pop()
                    elif t == "swap":
                        stack[-1], stack[-2] = stack[-2], stack[-1]
                    elif t == "over":
                        stack.append(stack[-2])
                    elif t == "rot":
                        stack.append(stack.pop(-3))
                    elif t in ("+", "-", "*", "/", "%", "<", "="):
                        a, b = stack[-2], stack[-1]
                        if not (isinstance(a, int) and isinstance(b, int)):
                            raise _Err(pos, "type error")
                        if t in "/%" and b == 0:
                            raise _Err(pos, "division by zero")
                        del stack[-2:]
                        if t == "+":
                            stack.append(a + b)
                        elif t == "-":
                            stack.append(a - b)
                        elif t == "*":
                            stack.append(a * b)
                        elif t == "/":
                            stack.append(a // b)
                        elif t == "%":
                            stack.append(a % b)
                        elif t == "<":
                            stack.append(1 if a < b else 0)
                        else:
                            stack.append(1 if a == b else 0)
                    elif t == "if":
                        c, x, y = stack[-3], stack[-2], stack[-1]
                        if not (isinstance(c, int) and isinstance(x, _Quote) and isinstance(y, _Quote)):
                            raise _Err(pos, "type error")
                        del stack[-3:]
                        q = x if c != 0 else y
                        frames.append(["seq", q.start, q.end])
                    elif t == "times":
                        q, k = stack[-2], stack[-1]
                        if not (isinstance(q, _Quote) and isinstance(k, int)):
                            raise _Err(pos, "type error")
                        if k < 0:
                            raise _Err(pos, "negative count")
                        del stack[-2:]
                        if q.start < q.end and k > 0:
                            frames.append(["times", q, k])
                    elif t == "while":
                        c, b = stack[-2], stack[-1]
                        if not (isinstance(c, _Quote) and isinstance(b, _Quote)):
                            raise _Err(pos, "type error")
                        del stack[-2:]
                        frames.append(["while", c, b, pos])
                        frames.append(["seq", c.start, c.end])
                    elif t == "call":
                        q = stack[-1]
                        if not isinstance(q, _Quote):
                            raise _Err(pos, "type error")
                        stack.pop()
                        frames.append(["seq", q.start, q.end])
                    elif t == "dip":
                        a, q = stack[-2], stack[-1]
                        if not isinstance(q, _Quote):
                            raise _Err(pos, "type error")
                        del stack[-2:]
                        frames.append(["push", a])
                        frames.append(["seq", q.start, q.end])
                    continue
                if t in words:
                    s, e = words[t]
                    frames.append(["seq", s, e])
                    continue
                raise _Err(pos, "unknown word '%s'" % t)
            elif kind == "times":
                if fr[2] == 0:
                    frames.pop()
                    continue
                fr[2] -= 1
                frames.append(["seq", fr[1].start, fr[1].end])
            elif kind == "while":
                # the condition quotation has just finished
                if not stack:
                    raise _Err(fr[3], "stack underflow")
                v = stack[-1]
                if not isinstance(v, int):
                    raise _Err(fr[3], "type error")
                stack.pop()
                if v != 0:
                    # run the body, then the condition again; this frame stays below both
                    frames.append(["seq", fr[1].start, fr[1].end])
                    frames.append(["seq", fr[2].start, fr[2].end])
                else:
                    frames.pop()
            else:  # push
                frames.pop()
                stack.append(fr[1])
    except _Err as e:
        return ("error", e.idx, e.msg)
    old = sys.getrecursionlimit()
    sys.setrecursionlimit(max(old, 200000))
    try:
        return ("ok", [_render(v, toks, match) for v in stack])
    finally:
        sys.setrecursionlimit(old)

import sys

_KEYWORDS = {"and", "or", "not", "in", "has"}
_F, _U, _T = 0, 1, 2
_ID0 = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_")
_ID1 = _ID0 | set("0123456789.")
_DIG = set("0123456789")


class _Err(Exception):
    def __init__(self, pos, msg):
        self.pos, self.msg = pos, msg


def _lex(q):
    toks, i, n = [], 0, len(q)
    while i < n:
        c = q[i]
        if c in " \t\n":
            i += 1
        elif c in "()[],=<>!":
            two = q[i:i + 2]
            if two in ("!=", "<=", ">="):
                toks.append(("op", two, i, two))
                i += 2
            elif c == "!":
                raise _Err(i, "unexpected character '!'")
            else:
                toks.append(("op" if c in "=<>" else c, c, i, c))
                i += 1
        elif c in _DIG or (c == "-" and i + 1 < n and q[i + 1] in _DIG):
            j = i + 1
            while j < n and q[j] in _DIG:
                j += 1
            toks.append(("lit", int(q[i:j]), i, q[i:j]))
            i = j
        elif c == '"':
            j, out = i + 1, []
            while True:
                if j >= n:
                    raise _Err(i, "unterminated string")
                if q[j] == "\\":
                    if j + 1 < n and q[j + 1] in '"\\':
                        out.append(q[j + 1])
                        j += 2
                        continue
                    raise _Err(j, "bad escape")
                if q[j] == '"':
                    break
                out.append(q[j])
                j += 1
            toks.append(("lit", "".join(out), i, q[i:j + 1]))
            i = j + 1
        elif c in _ID0:
            j = i + 1
            while j < n and q[j] in _ID1:
                j += 1
            w = q[i:j]
            toks.append((w if w in _KEYWORDS else "field", w, i, w))
            i = j
        else:
            raise _Err(i, "unexpected character '%s'" % c)
    toks.append(("end", None, n, ""))
    return toks


class _P:
    def __init__(self, toks):
        self.t, self.k = toks, 0

    def fail(self):
        kind, _, pos, text = self.t[self.k]
        if kind == "end":
            raise _Err(pos, "unexpected end of input")
        raise _Err(pos, "unexpected token '%s'" % text)

    def kind(self):
        return self.t[self.k][0]

    def eat(self, kind):
        if self.kind() != kind:
            self.fail()
        tok = self.t[self.k]
        self.k += 1
        return tok

    def orexpr(self):
        parts = [self.andexpr()]
        while self.kind() == "or":
            self.k += 1
            parts.append(self.andexpr())
        return parts[0] if len(parts) == 1 else ("or", parts)

    def andexpr(self):
        parts = [self.notexpr()]
        while self.kind() == "and":
            self.k += 1
            parts.append(self.notexpr())
        return parts[0] if len(parts) == 1 else ("and", parts)

    def notexpr(self):
        count = 0
        while self.kind() == "not":
            self.k += 1
            count += 1
        node = self.primary()
        return ("not", node) if count % 2 else (("notnot", node) if count else node)

    def primary(self):
        kind = self.kind()
        if kind == "(":
            self.k += 1
            node = self.orexpr()
            self.eat(")")
            return node
        if kind == "has":
            self.k += 1
            return ("has", self.eat("field")[1])
        if kind == "field":
            name = self.t[self.k][1]
            self.k += 1
            if self.kind() == "op":
                op = self.t[self.k][1]
                self.k += 1
                return ("cmp", name, op, self.eat("lit")[1])
            if self.kind() == "in":
                self.k += 1
                self.eat("[")
                vals = [self.eat("lit")[1]]
                while self.kind() == ",":
                    self.k += 1
                    vals.append(self.eat("lit")[1])
                self.eat("]")
                return ("in", name, vals)
            self.fail()
        self.fail()


def _ev(node, rec):
    tag = node[0]
    if tag == "cmp":
        _, name, op, lit = node
        if name not in rec:
            return _U
        v = rec[name]
        if type(v) is not type(lit):
            return _F if op == "=" else (_T if op == "!=" else _U)
        if op == "=":
            r = v == lit
        elif op == "!=":
            r = v != lit
        elif op == "<":
            r = v < lit
        elif op == "<=":
            r = v <= lit
        elif op == ">":
            r = v > lit
        else:
            r = v >= lit
        return _T if r else _F
    if tag == "in":
        if node[1] not in rec:
            return _U
        v = rec[node[1]]
        return _T if any(type(v) is type(x) and v == x for x in node[2]) else _F
    if tag == "has":
        return _T if node[1] in rec else _F
    if tag == "not":
        return 2 - _ev(node[1], rec)
    if tag == "notnot":
        return _ev(node[1], rec)
    if tag == "and":
        r = _T
        for p in node[1]:
            r = min(r, _ev(p, rec))
            if r == _F:
                break
        return r
    r = _F
    for p in node[1]:
        r = max(r, _ev(p, rec))
        if r == _T:
            break
    return r


def filter_records(query, records):
    old = sys.getrecursionlimit()
    sys.setrecursionlimit(max(old, 100000))
    try:
        p = _P(_lex(query))
        tree = p.orexpr()
        if p.kind() != "end":
            p.fail()
        return ("ok", [i for i, rec in enumerate(records) if _ev(tree, rec) == _T])
    except _Err as e:
        return ("error", e.pos, e.msg)
    finally:
        sys.setrecursionlimit(old)

import sys

_TWO = ("<=", ">=", "==", "!=")
_ONE = set("+-*/%^()?:<>")
_CMP = ("<", "<=", ">", ">=", "==", "!=")


class _Err(Exception):
    def __init__(self, pos, msg):
        self.pos, self.msg = pos, msg


def _tokens(src):
    out, i, n = [], 0, len(src)
    while i < n:
        c = src[i]
        if c == " ":
            i += 1
        elif c.isdigit() and c in "0123456789":
            j = i
            while j < n and src[j] in "0123456789":
                j += 1
            out.append(("int", src[i:j], i))
            i = j
        elif c == "_" or ("a" <= c <= "z"):
            j = i
            while j < n and (src[j] == "_" or "a" <= src[j] <= "z" or src[j] in "0123456789"):
                j += 1
            out.append(("name", src[i:j], i))
            i = j
        elif src[i:i + 2] in _TWO:
            out.append(("op", src[i:i + 2], i))
            i += 2
        elif c in _ONE:
            out.append(("op", c, i))
            i += 1
        else:
            out.append(("bad", c, i))
            i += 1
    out.append(("eof", "", n))
    return out


class _Parser:
    def __init__(self, toks):
        self.t, self.k = toks, 0

    def peek(self):
        return self.t[self.k]

    def fail(self):
        kind, text, pos = self.t[self.k]
        if kind == "eof":
            raise _Err(pos, "unexpected end of input")
        if kind == "bad":
            raise _Err(pos, "unexpected character '%s'" % text)
        raise _Err(pos, "unexpected token '%s'" % text)

    def is_op(self, *ops):
        kind, text, _ = self.t[self.k]
        return kind == "op" and text in ops

    def expect(self, op):
        if not self.is_op(op):
            self.fail()
        self.k += 1

    def cond(self):
        c = self.cmp()
        if self.is_op("?"):
            pos = self.peek()[2]
            self.k += 1
            a = self.cond()
            self.expect(":")
            b = self.cond()
            return ("?", pos, c, a, b)
        return c

    def cmp(self):
        left = self.sum()
        if self.is_op(*_CMP):
            _, op, pos = self.peek()
            self.k += 1
            right = self.sum()
            return (op, pos, left, right)
        return left

    def sum(self):
        left = self.term()
        while self.is_op("+", "-"):
            _, op, pos = self.peek()
            self.k += 1
            left = (op, pos, left, self.term())
        return left

    def term(self):
        left = self.unary()
        while self.is_op("*", "/", "%"):
            _, op, pos = self.peek()
            self.k += 1
            left = (op, pos, left, self.unary())
        return left

    def unary(self):
        if self.is_op("-"):
            pos = self.peek()[2]
            self.k += 1
            return ("neg", pos, self.unary())
        return self.power()

    def power(self):
        base = self.atom()
        if self.is_op("^"):
            pos = self.peek()[2]
            self.k += 1
            return ("^", pos, base, self.unary())
        return base

    def atom(self):
        kind, text, pos = self.peek()
        if kind == "int":
            self.k += 1
            return ("int", pos, int(text))
        if kind == "name":
            self.k += 1
            return ("name", pos, text)
        if self.is_op("("):
            self.k += 1
            e = self.cond()
            self.expect(")")
            return e
        self.fail()


def _eval(node, env):
    tag, pos = node[0], node[1]
    if tag == "int":
        return node[2]
    if tag == "name":
        if node[2] not in env:
            raise _Err(pos, "unknown name '%s'" % node[2])
        return env[node[2]]
    if tag == "neg":
        return -_eval(node[2], env)
    if tag == "?":
        return _eval(node[3], env) if _eval(node[2], env) != 0 else _eval(node[4], env)
    a = _eval(node[2], env)
    b = _eval(node[3], env)
    if tag == "+":
        return a + b
    if tag == "-":
        return a - b
    if tag == "*":
        return a * b
    if tag in ("/", "%"):
        if b == 0:
            raise _Err(pos, "division by zero")
        return a // b if tag == "/" else a % b
    if tag == "^":
        if b < 0:
            raise _Err(pos, "negative exponent")
        if b > 256:
            raise _Err(pos, "exponent too large")
        return a ** b
    return int({"<": a < b, "<=": a <= b, ">": a > b, ">=": a >= b, "==": a == b, "!=": a != b}[tag])


def evaluate(src, env):
    old = sys.getrecursionlimit()
    sys.setrecursionlimit(max(old, 1_000_000))
    try:
        p = _Parser(_tokens(src))
        tree = p.cond()
        if p.peek()[0] != "eof":
            p.fail()
        return ("ok", _eval(tree, env))
    except _Err as e:
        return ("error", e.pos, e.msg)
    finally:
        sys.setrecursionlimit(old)

def leaderboard_ranks(submissions):
    n = len(submissions)
    if n == 0:
        return []
    # every possible leaderboard key is (-score, index) of some submission; rank them offline
    order = sorted(range(n), key=lambda i: (-submissions[i][1], i))
    pos = [0] * n
    for r, i in enumerate(order):
        pos[i] = r + 1  # 1-based Fenwick position
    tree = [0] * (n + 1)

    def add(i, d):
        while i <= n:
            tree[i] += d
            i += i & -i

    def prefix(i):
        s = 0
        while i > 0:
            s += tree[i]
            i -= i & -i
        return s

    best = {}  # player -> (score, submission index that set it)
    out = []
    for i, (player, score) in enumerate(submissions):
        cur = best.get(player)
        if cur is None or score > cur[0]:
            if cur is not None:
                add(pos[cur[1]], -1)
            cur = (score, i)
            best[player] = cur
            add(pos[i], 1)
        out.append(prefix(pos[cur[1]]))
    return out

_DIG = "0123456789abcdefghijklmnopqrstuvwxyz"


def _int_to_base(n, b):
    if n == 0:
        return "0"
    # chunked conversion: peel off as many digits per big division as fit comfortably
    k = 1
    while b ** (k + 1) < 2 ** 60:
        k += 1
    big = b ** k
    chunks = []
    while n:
        n, r = divmod(n, big)
        chunks.append(r)
    out = []
    for i, c in enumerate(reversed(chunks)):
        s = []
        for _ in range(k):
            c, d = divmod(c, b)
            s.append(_DIG[d])
        s = "".join(reversed(s))
        out.append(s.lstrip("0") or "0" if i == 0 else s)
    return "".join(out)


def format_base(p, q, base, k):
    if q == 0 or not (2 <= base <= 36) or k < 0:
        raise ValueError("bad arguments")
    neg = (p < 0) != (q < 0) and p != 0
    p, q = abs(p), abs(q)
    ip, r = divmod(p, q)
    # fractional digits by long division (remainder always < q, so each step is cheap)
    frac = []
    for _ in range(k):
        r *= base
        d, r = divmod(r, q)
        frac.append(d)
    # N = ip * base**k + frac digits; decide rounding from the final remainder
    twice = 2 * r
    up = twice > q
    if twice == q and r != 0:
        # tie: round to make N even. parity of N:
        if base % 2 == 0:
            par = frac[-1] % 2 if k else ip % 2
        else:
            par = (ip + sum(frac)) % 2  # base odd: base**j is odd, N = sum of digit*odd
        up = par == 1
    if up:
        i = k - 1
        while i >= 0 and frac[i] == base - 1:
            frac[i] = 0
            i -= 1
        if i >= 0:
            frac[i] += 1
        else:
            ip += 1
    while frac and frac[-1] == 0:
        frac.pop()
    if ip == 0 and not frac:
        return "0"
    s = _int_to_base(ip, base)
    if frac:
        s += "." + "".join(_DIG[d] for d in frac)
    return ("-" if neg else "") + s

import re

_GRAMMAR = re.compile(r"([+-]?)([0-9]*)(?:\.([0-9]*))?(?:[eE]([+-]?[0-9]+))?")


def decimal_to_half_bits(s):
    if not isinstance(s, str):
        raise ValueError("invalid literal")
    m = _GRAMMAR.fullmatch(s)
    if not m:
        raise ValueError("invalid literal")
    sign, ip, fp, ex = m.group(1), m.group(2), m.group(3), m.group(4)
    fp = fp or ""
    if not ip and not fp:
        raise ValueError("invalid literal")
    neg = 0x8000 if sign == "-" else 0
    allds = ip + fp
    digits = allds.lstrip("0")
    if not digits:
        return neg
    # decimal exponent of the last digit of `allds`; absurd exponents are clamped (still decisive)
    if ex is None:
        e_in = 0
    else:
        mag = ex.lstrip("+-").lstrip("0") or "0"
        e_in = int(mag) if len(mag) <= 15 else 10 ** 15
        if ex.startswith("-"):
            e_in = -e_in
    nd = len(digits)
    e10 = e_in - len(fp)
    # only ~30 significant digits can matter: keep 40 plus a sticky digit for anything nonzero beyond
    if nd > 40:
        tail_nonzero = digits[40:].strip("0") != ""
        e10 += nd - 40
        digits = digits[:40]
        if tail_nonzero:
            digits += "1"
            e10 -= 1
        nd_eff = len(digits)
    else:
        nd_eff = nd
    mant = int(digits)
    # magnitude test uses the true digit count: value in [10**(nd-1+E), 10**(nd+E)), E = exponent of last digit
    nd, e10_true = nd, e10 + nd_eff - nd
    if nd - 1 + e10_true >= 5:      # >= 100000 > 65520 -> overflow
        return neg | 0x7C00
    if nd + e10_true <= -8:         # < 1e-8 < 2**-25 -> rounds to zero
        return neg
    if e10 >= 0:
        num, den = mant * 10 ** e10, 1
    else:
        num, den = mant, 10 ** (-e10)
    # e = floor(log2(num/den))
    e = num.bit_length() - den.bit_length()
    if (num << -e if e < 0 else num) < (den << e if e > 0 else den):
        e -= 1
    ee = max(e, -14)
    sh = 10 - ee                # scaled = num/den * 2**sh
    if sh >= 0:
        a, b = num << sh, den
    else:
        a, b = num, den << -sh
    n, r = divmod(a, b)
    if 2 * r > b or (2 * r == b and n & 1):
        n += 1
    if n == 2048:
        n = 1024
        ee += 1
    if ee > 15:
        return neg | 0x7C00
    if n < 1024:
        return neg | n
    return neg | ((ee + 15) << 10) | (n - 1024)

from bisect import bisect_left, bisect_right


def run_ops(ops):
    # persistent segment tree over the offline-compressed set of keys that can ever be stored
    keys = sorted({op[2] for op in ops if op[0] in ("set", "del")})
    m = max(len(keys), 1)
    idx = {k: i for i, k in enumerate(keys)}
    L, R, C, S = [0], [0], [0], [0]  # node 0 is the shared empty node
    roots = [0]
    out = []

    def update(root, pos, present, value):
        # returns new root after setting leaf `pos`
        path = []
        node, lo, hi = root, 0, m - 1
        while lo < hi:
            mid = (lo + hi) >> 1
            path.append((node, pos <= mid))
            if pos <= mid:
                node, hi = L[node], mid
            else:
                node, lo = R[node], mid + 1
        L.append(0); R.append(0); C.append(1 if present else 0); S.append(value if present else 0)
        new = len(C) - 1
        for node, went_left in reversed(path):
            if went_left:
                l, r = new, R[node]
            else:
                l, r = L[node], new
            L.append(l); R.append(r); C.append(C[l] + C[r]); S.append(S[l] + S[r])
            new = len(C) - 1
        return new

    def leaf(root, pos):
        node, lo, hi = root, 0, m - 1
        while lo < hi and node:
            mid = (lo + hi) >> 1
            if pos <= mid:
                node, hi = L[node], mid
            else:
                node, lo = R[node], mid + 1
        return node

    def range_query(root, a, b):
        cnt = tot = 0
        stack = [(root, 0, m - 1)]
        while stack:
            node, lo, hi = stack.pop()
            if not node or hi < a or lo > b:
                continue
            if a <= lo and hi <= b:
                cnt += C[node]
                tot += S[node]
                continue
            mid = (lo + hi) >> 1
            stack.append((L[node], lo, mid))
            stack.append((R[node], mid + 1, hi))
        return cnt, tot

    def kth(root, k):
        node, lo, hi = root, 0, m - 1
        while lo < hi:
            mid = (lo + hi) >> 1
            if C[L[node]] >= k:
                node, hi = L[node], mid
            else:
                k -= C[L[node]]
                node, lo = R[node], mid + 1
        return keys[lo]

    def valid(v):
        return type(v) is int and 0 <= v < len(roots)

    for op in ops:
        name, v = op[0], op[1]
        if not valid(v):
            out.append("BADVER")
            continue
        root = roots[v]
        if name == "set":
            roots.append(update(root, idx[op[2]], True, op[3]))
            out.append(len(roots) - 1)
        elif name == "del":
            if op[2] not in idx or not C[leaf(root, idx[op[2]])]:
                out.append("NOKEY")
            else:
                roots.append(update(root, idx[op[2]], False, 0))
                out.append(len(roots) - 1)
        elif name == "get":
            k = op[2]
            if k in idx:
                nd = leaf(root, idx[k])
                out.append(S[nd] if C[nd] else None)
            else:
                out.append(None)
        elif name in ("count", "sum"):
            lo, hi = op[2], op[3]
            a, b = bisect_left(keys, lo), bisect_right(keys, hi) - 1
            cnt, tot = range_query(root, a, b) if a <= b else (0, 0)
            out.append(cnt if name == "count" else tot)
        elif name == "kth":
            k = op[2]
            out.append(kth(root, k) if 1 <= k <= C[root] else None)
    return out

from bisect import bisect_left, bisect_right


def run_ops(ops):
    starts, ends, labs = [], [], []  # disjoint, sorted, maximal (merged) runs
    totals = {}
    out = []

    def merge_range(a, b):
        k = max(a, 1)
        while k < min(b, len(starts)):
            if ends[k - 1] == starts[k] and labs[k - 1] == labs[k]:
                ends[k - 1] = ends[k]
                del starts[k], ends[k], labs[k]
                b -= 1
            else:
                k += 1

    def cover(l, r, lab):
        # lab None = erase; returns (overlap with any label, overlap with same label)
        i = bisect_right(ends, l)
        j = bisect_left(starts, r)
        covered = same = 0
        for k in range(i, j):
            ov = min(ends[k], r) - max(starts[k], l)
            covered += ov
            totals[labs[k]] -= ov
            if labs[k] == lab:
                same += ov
        pieces = []
        if i < j and starts[i] < l:
            pieces.append((starts[i], l, labs[i]))
        if lab is not None:
            pieces.append((l, r, lab))
            totals[lab] = totals.get(lab, 0) + (r - l)
        if i < j and ends[j - 1] > r:
            pieces.append((r, ends[j - 1], labs[j - 1]))
        starts[i:j] = [p[0] for p in pieces]
        ends[i:j] = [p[1] for p in pieces]
        labs[i:j] = [p[2] for p in pieces]
        merge_range(i, i + len(pieces) + 1)
        return covered, same

    for op in ops:
        name = op[0]
        if name == "paint":
            _, l, r, lab = op
            if l >= r:
                out.append(0)
                continue
            covered, same = cover(l, r, lab)
            out.append((r - l) - same)
        elif name == "erase":
            _, l, r = op
            if l >= r:
                out.append(0)
                continue
            covered, _ = cover(l, r, None)
            out.append(covered)
        elif name == "at":
            p = op[1]
            k = bisect_right(starts, p) - 1
            out.append(labs[k] if k >= 0 and ends[k] > p else None)
        elif name == "runs":
            out.append(len(starts))
        elif name == "total":
            out.append(totals.get(op[1], 0))
        elif name == "next_change":
            p = op[1]
            k = bisect_right(starts, p) - 1
            if k >= 0 and ends[k] > p:
                out.append(ends[k])
            else:
                out.append(starts[k + 1] if k + 1 < len(starts) else None)
    return out

import heapq
from collections import OrderedDict


def run_cache(capacity, ops):
    if not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be a positive int")

    store = OrderedDict()  # key -> [value, expires_at or None, version]; oldest use first
    expiry = []            # (expires_at, version, key) for entries that can expire
    version = 0
    out = []
    last_t = None

    def purge(t):
        while expiry and expiry[0][0] <= t:
            _, ver, key = heapq.heappop(expiry)
            entry = store.get(key)
            if entry is not None and entry[2] == ver:
                del store[key]

    for op in ops:
        kind, t = op[0], op[1]
        if last_t is not None and t < last_t:
            raise ValueError("operations must have non-decreasing timestamps")
        last_t = t

        if kind == "put":
            _, _, key, value, ttl = op
            if ttl is not None and (not isinstance(ttl, int) or ttl < 1):
                raise ValueError("ttl must be None or a positive int")
            purge(t)
            expires_at = None if ttl is None else t + ttl
            version += 1
            if expires_at is not None:
                heapq.heappush(expiry, (expires_at, version, key))
            if key in store:
                store[key] = [value, expires_at, version]
                store.move_to_end(key)
                continue
            if len(store) >= capacity:
                store.popitem(last=False)
            store[key] = [value, expires_at, version]

        elif kind == "get":
            purge(t)
            key = op[2]
            entry = store.get(key)
            if entry is None:
                out.append(None)
            else:
                store.move_to_end(key)
                out.append(entry[0])

        elif kind == "size":
            purge(t)
            out.append(len(store))

        else:
            raise ValueError("unknown operation %r" % (kind,))

    return out

import heapq
from collections import defaultdict


def window_medians(readings, k):
    if not isinstance(k, int) or k < 1:
        raise ValueError("k must be a positive int")

    low = []    # max-heap via negation: the smaller half, its top is the median
    high = []   # min-heap: the larger half
    delayed = defaultdict(int)  # value -> pending lazy deletions
    sizes = {"low": 0, "high": 0}  # live (not yet deleted) element counts
    out = []

    def prune(heap, sign):
        # drop deleted values sitting on top of a heap
        while heap and delayed[sign * heap[0]]:
            delayed[sign * heap[0]] -= 1
            heapq.heappop(heap)

    def rebalance():
        # invariant: sizes["low"] == sizes["high"] or sizes["low"] == sizes["high"] + 1
        if sizes["low"] > sizes["high"] + 1:
            heapq.heappush(high, -heapq.heappop(low))
            sizes["low"] -= 1
            sizes["high"] += 1
            prune(low, -1)
        elif sizes["low"] < sizes["high"]:
            heapq.heappush(low, -heapq.heappop(high))
            sizes["high"] -= 1
            sizes["low"] += 1
            prune(high, 1)

    def add(x):
        if not low or x <= -low[0]:
            heapq.heappush(low, -x)
            sizes["low"] += 1
        else:
            heapq.heappush(high, x)
            sizes["high"] += 1
        rebalance()

    def remove(x):
        delayed[x] += 1
        if x <= -low[0]:
            sizes["low"] -= 1
            if x == -low[0]:
                prune(low, -1)
        else:
            sizes["high"] -= 1
            if x == high[0]:
                prune(high, 1)
        rebalance()

    for i, x in enumerate(readings):
        if x is not None:
            add(x)
        if i >= k and readings[i - k] is not None:
            remove(readings[i - k])
        out.append(-low[0] if sizes["low"] else None)
    return out

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "->")
ONE_CHAR_OPS = "<>=+-*/(),"
ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_ident_char(ch):
    return _is_ident_start(ch) or _is_digit(ch)


def tokenize(src):
    tokens = []
    n = len(src)
    i, line, col = 0, 1, 1

    def fail(at_line, at_col, message):
        raise ValueError("line %d col %d: %s" % (at_line, at_col, message))

    while i < n:
        ch = src[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue
        if ch == " " or ch == "\t":
            i += 1
            col += 1
            continue
        if ch == "#":
            end = src.find("\n", i)
            i = n if end == -1 else end
            continue

        if _is_digit(ch):
            j = i
            while j < n and _is_digit(src[j]):
                j += 1
            is_float = False
            if j + 1 < n and src[j] == "." and _is_digit(src[j + 1]):
                j += 1
                while j < n and _is_digit(src[j]):
                    j += 1
                is_float = True
            if j < n and src[j] in "eE":
                k = j + 1
                if k < n and src[k] in "+-":
                    k += 1
                if k < n and _is_digit(src[k]):
                    while k < n and _is_digit(src[k]):
                        k += 1
                    j = k
                    is_float = True
            text = src[i:j]
            tokens.append(("NUMBER", float(text) if is_float else int(text), line, col))
            col += j - i
            i = j
            continue

        if _is_ident_start(ch):
            j = i
            while j < n and _is_ident_char(src[j]):
                j += 1
            tokens.append(("IDENT", src[i:j], line, col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            chars = []
            while True:
                if j >= n or src[j] == "\n":
                    fail(line, col, "unterminated string")
                c = src[j]
                if c == '"':
                    j += 1
                    break
                if c == "\\":
                    if j + 1 >= n or src[j + 1] == "\n":
                        fail(line, col, "unterminated string")
                    if src[j + 1] not in ESCAPES:
                        fail(line, col + (j - i), "bad escape")
                    chars.append(ESCAPES[src[j + 1]])
                    j += 2
                    continue
                chars.append(c)
                j += 1
            tokens.append(("STRING", "".join(chars), line, col))
            col += j - i
            i = j
            continue

        if src[i:i + 2] in TWO_CHAR_OPS:
            tokens.append(("OP", src[i:i + 2], line, col))
            i += 2
            col += 2
            continue
        if ch in ONE_CHAR_OPS:
            tokens.append(("OP", ch, line, col))
            i += 1
            col += 1
            continue

        fail(line, col, "unexpected character %r" % ch)

    return tokens
